<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { signInWithGoogle, friendlyError, isCancelled } from '@/services/auth'
import { celebrateLogin } from '@/utils/celebrate'
import AnimatedBrandHero from '@/components/landing/AnimatedBrandHero.vue'

const router = useRouter()
const loading = ref(false), success = ref(false), error = ref('')
const PERKS = [{ icon: 'bi-compass', color: 'var(--gol-cyan)', title: 'Find stuff to do', text: 'Picked for your vibe & budget' }, { icon: 'bi-trophy', color: 'var(--gol-yellow)', title: 'Earn badges', text: 'Points, streaks, levels' }, { icon: 'bi-people', color: 'var(--gol-coral)', title: 'OPENJIO!', text: 'Rope in friends, or make new ones' }]
async function onGoogle() { error.value = ''; loading.value = true; try { await signInWithGoogle(); success.value = true; try { celebrateLogin() } catch { /* decoration only */ } await new Promise((resolve) => setTimeout(resolve, 700)); await router.push({ name: 'map' }) } catch (err) { if (!isCancelled(err)) error.value = friendlyError(err) } finally { loading.value = false } }
</script>

<template>
  <main class="login-page">
    <div class="login-layout">
      <AnimatedBrandHero />
      <section class="login-card" :class="{ 'is-success': success }">
        <RouterLink :to="{ name: 'landing' }" class="back-link"><i class="bi bi-arrow-left"></i> Back</RouterLink>
        <h2 class="gol-title mb-2" data-testid="login-title">{{ success ? 'You’re in! 🎉' : 'Ready to get out?' }}</h2>
        <p class="muted mb-4">Log in or sign up with your Google account.</p>
        <div v-if="error" class="error-box mb-3" role="alert" data-testid="login-error"><i class="bi bi-exclamation-circle-fill"></i> {{ error }}</div>
        <button type="button" class="google-btn" :disabled="loading || success" data-testid="google-signin" @click="onGoogle">
          <span v-if="loading && !success" class="spinner-border spinner-border-sm" aria-hidden="true"></span>
          <i v-else-if="success" class="bi bi-check-circle-fill ok-icon" aria-hidden="true"></i>
          <svg v-else class="google-g" viewBox="0 0 48 48" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg>
          <span>{{ success ? 'Taking you in…' : loading ? 'Waiting for Google…' : 'Continue with Google' }}</span>
        </button>
        <ul class="perks list-unstyled mt-4 mb-0">
          <li v-for="(perk, index) in PERKS" :key="perk.title" class="perk" :style="{ '--i': index }">
            <span class="gol-icon-tile perk-tile" :style="{ background: perk.color }"><i class="bi" :class="perk.icon"></i></span>
            <span><span class="d-block perk-title">{{ perk.title }}</span><span class="d-block perk-text">{{ perk.text }}</span></span>
          </li>
        </ul>
      </section>
    </div>
  </main>
</template>

